"""uBlacklist リスト生成 (P7a)。

- 常設正規表現 3 本 (`.com.xx` ダークパターン / 短縮 `.co` / Punycode) は常に出力する。
- `.co` 短縮形・Punycode・`.com.xx` に該当するドメインは個別登録しない (常設ルールで足りる)。
- 追記は冪等 (同じ入力で同じ出力)。
"""

from __future__ import annotations

import re
from collections.abc import Iterable

HEADER = (
    "# uBlacklist - scam stores JP (Hermes nightly)\n"
    "# generated by scam_hunter; permanent rules first, then per-domain entries.\n"
    "# 手動編集しない。夜間ジョブが PR 経由で更新する。\n"
)

SECTION_MARKER = "## Hermes nightly"

PERMANENT_RULES: tuple[str, ...] = (
    r"/https?:\/\/.*[\.\-](com|net|org)[\.\-][a-z]{2}\/.*/",
    r"/https?:\/\/.*\.co\/.*/",
    r"/https?:\/\/(?:[a-z0-9-]+\.)*xn--[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,8}\/.*/",
)

_PERMANENT_RE = tuple(re.compile(r[1:-1].replace("\\/", "/")) for r in PERMANENT_RULES)

_DOMAIN_RE = re.compile(r"^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$")
_ENTRY_RE = re.compile(r"^\*://\*\.(.+?)/\*$")


def _normalise(domain: str) -> str:
    return (domain or "").strip().lower().rstrip(".")


def is_permanent_shape(domain: str) -> bool:
    """個別登録せず常設正規表現に委ねる形か。"""
    d = _normalise(domain)
    if not d:
        return True
    if d.endswith(".co") or ".co/" in d:
        return True
    if "xn--" in d:
        return True
    labels = d.split(".")
    puny = [p for p in labels if p in ("com", "net", "org")]
    # x.com.xx / y.net.zz
    return bool(puny and len(labels) >= 3 and len(labels[-1]) == 2)


def build_entries(domains: Iterable[str]) -> list[str]:
    out: set[str] = set()
    for raw in domains:
        d = _normalise(raw)
        if not d or "/" in d or "?" in d or " " in d or ".." in d:
            continue
        if not _DOMAIN_RE.match(d):
            continue
        if d.startswith("*"):
            continue
        if is_permanent_shape(d):
            continue
        out.add(f"*://*.{d}/*")
    return sorted(out, key=lambda e: _ENTRY_RE.match(e).group(1))


def existing_entries(text: str) -> list[str]:
    return [ln.strip() for ln in (text or "").splitlines() if _ENTRY_RE.match(ln.strip())]


def render_list(domains: Iterable[str]) -> str:
    entries = build_entries(domains)
    lines = [HEADER.rstrip("\n"), "", "## Permanent rules (regex)"]
    lines += list(PERMANENT_RULES)
    lines += ["", SECTION_MARKER]
    lines += entries
    return "\n".join(lines).rstrip("\n") + "\n"


def merge_list(existing: str, domains: Iterable[str]) -> str:
    """既存テキストにドメインを追記する (冪等)。常設ルールは必ず含める。"""
    existing = existing or ""
    known: list[str] = []
    seen: set[str] = set()
    for entry in existing_entries(existing):
        if entry not in seen:
            seen.add(entry)
            known.append(entry)
    for entry in build_entries(domains):
        if entry not in seen:
            seen.add(entry)
            known.append(entry)
    known.sort(key=lambda e: _ENTRY_RE.match(e).group(1))

    body_lines = existing.splitlines()
    keep: list[str] = []
    for ln in body_lines:
        s = ln.strip()
        if not s:
            continue
        if _ENTRY_RE.match(s):
            continue
        if s in PERMANENT_RULES:
            continue
        if s.startswith("## Permanent rules") or s == SECTION_MARKER:
            continue
        keep.append(ln.rstrip())

    lines: list[str] = []
    if keep:
        lines += keep
    else:
        lines += HEADER.rstrip("\n").splitlines()
    lines += ["", "## Permanent rules (regex)"]
    lines += list(PERMANENT_RULES)
    lines += ["", SECTION_MARKER]
    lines += known
    return "\n".join(lines).rstrip("\n") + "\n"


def validate(text: str) -> list[str]:
    problems: list[str] = []
    if not (text or "").strip():
        return ["empty list"]
    for rule in PERMANENT_RULES:
        if rule not in text:
            problems.append(f"permanent rule missing: {rule}")
    if SECTION_MARKER not in text:
        problems.append(f"section marker missing: {SECTION_MARKER}")
    entries = existing_entries(text)
    dupes = {e for e in entries if entries.count(e) > 1}
    if dupes:
        problems.append(f"duplicate entries: {sorted(dupes)}")
    for e in entries:
        if is_permanent_shape(_ENTRY_RE.match(e).group(1)):
            problems.append(f"permanent-shape entry registered individually: {e}")
    return problems


def domains_to_remove(text: str, domains: Iterable[str]) -> str:
    """P8: 失効したドメインの行を取り除く。常設ルールは残す。"""
    drop = {f"*://*.{_normalise(d)}/*" for d in domains}
    lines = [ln for ln in (text or "").splitlines() if ln.strip() not in drop]
    return "\n".join(lines).rstrip("\n") + "\n"
